// neemKaroliBaba_te.dart
// Neem Karoli Baba quotes and articles (Malyalam)

import '../articlesquotes.dart';

final neemKaroliBabaSaint = Saint(
  'baba_neeb_karori',
  'Neem Karoli Baba',
  'assets/images/baba_neeb_karori.jpg',
  [
    'എല്ലാവരെയും സ്നേഹിക്കുക, എല്ലാവരെയും സേവിക്കുക, ദൈവത്തെ ഓർക്കുക.',
    'എല്ലാവിലെയും ദൈവത്തെ കാണുന്നത് അതിനെ മനസ്സിലാക്കാൻ ശ്രമിക്കുന്നതിനെക്കാൾ നല്ലതാണ്.',
    'ദൈവത്തെ ആരാധിക്കുന്നതിനുള്ള ഏറ്റവും നല്ല രൂപം എല്ലാ രൂപങ്ങളാണ്.',
    'നിങ്ങൾ ചെയ്യേണ്ടത് മറ്റൊരാളോടു ചെയ്യുക, എന്നാൽ അവരെ നിങ്ങളുടെ ഹൃദയത്തിൽ നിന്നും പുറത്താക്കരുത്.',
    'സത്യത്തെ പറയുക. സത്യത്തെ പറയുക. സത്യത്തെ പറയുക.',
    'ഗുരു ഒരു വ്യക്തിയല്ല. ഗുരു തന്നെയാണ് കൃപ.',
    'നിങ്ങൾ ദൈവത്തെ കാണാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, ആഗ്രഹങ്ങളെ നശിപ്പിക്കുക. ആഗ്രഹങ്ങൾ മനസ്സിൽ ആണ്. നിങ്ങൾക്ക് എന്തെങ്കിലും ഒരു ആഗ്രഹം ഉണ്ടെങ്കിൽ, അതിന്മേൽ പ്രവർത്തിക്കേണ്ട, അത് നഷ്ടപ്പെടും.',
    'ബന്ധം സാക്ഷാത്കാരത്തിന് ഏറ്റവും ശക്തമായ തടസ്സമാണ്.',
    'ദുഃഖം എല്ലാം മനസ്സിലാണ്.',
    'പ്രേമം ഏറ്റവും ശക്തമായ ഔഷധമാണ്.',
    'എല്ലാ പ്രവർത്തനങ്ങളും പ്രാർത്ഥനയാണ്. എല്ലാ മരങ്ങളും ഇച്ഛാപൂരകമാണ്. എല്ലാ വെള്ളവും ഗംഗയാണ്. എല്ലാ ഭൂമിയും വൃന്ദാവനമാണ്.',
    'നായയെപ്പോലെ ആയിരിക്കുക, ലഭിക്കുന്നതെല്ലാം കഴിക്കുക, എവിടെയെങ്കിലും ഉറങ്ങുക.',
    'നിന്റെ ഹൃദയത്തിൽ ആരെയും പുറത്താക്കരുത്.',
    'മറ്റുള്ളവരെ സേവിച്ചാൽ, നിങ്ങൾ ദൈവത്തെ സേവിക്കുന്നു.',
    'സേവിക്കുക, സ്നേഹിക്കുക, നൽകുക, ശുദ്ധമാക്കുക, ധ്യാനിക്കുക, തിരിച്ചറിഞ്ഞുക.',
    'എല്ലാവരിലും ദൈവത്തെ കാണുക. ഇത് വഴിയാണ്.',
    'ഭാവിയെ സംരക്ഷിക്കാൻ ഏറ്റവും നല്ല മാർഗം ഇപ്പോഴത്തെ നിമിഷത്തെ സംരക്ഷിക്കുകയാണ്.',
    'എന്തിനും ബന്ധപ്പെടേണ്ട. ബന്ധം ദു:ഖം ഉണ്ടാക്കുന്നു.',
    'അഹംഭാവം ഒരു ഭൂതമാണ്. അതിനെ വിട്ടുകളയൂ.',
    'ക്രിസ്തു ക്രൂശിൽ മരിച്ചപ്പോൾ, ഹിറ്റ്ലർ യുദ്ധത്തിൽ മരിച്ചു. വ്യത്യാസം എവിടെയാണ്? ക്രൂശിൽ ദു:ഖം അനുഭവിച്ചവൻ യുദ്ധത്തിൽ പോലും ദു:ഖം അനുഭവിച്ചു.',
    'പ്രതിയൊരു സന്യാസിയ്ക്കും ഒരു ഭവനുണ്ട്, ഓരോ പാപിയ്ക്കും ഒരു ഭാവിയുണ്ട്.',
    'ഭക്തി ലക്ഷ്യരഹിതമായ സ്നേഹമാണ്.',
    'ഹനുമാൻ രാമൻ ദൈവമാണെന്ന് അറിയുന്നു, അതിനാൽ തന്നെ അദ്ദേഹം അത്ര ശക്തവാനാണ്.',
    'രാം, രാം, രാം - ഇത് ഏറ്റവും മഹാനായ മന്ത്രമാണ്.',
    'മനുഷ്യരെ ഭക്ഷിപ്പിക്കുക. മനുഷ്യരെ സേവിക്കുക. അതാണ് ഉന്നതമായ ധർമ്മം.',
    'പ്രേമം നൽകുക. പ്രേമം ആയിരിക്കുക. പ്രേമത്തിൽ ജീവിക്കുക.',
    'ദൈവം സ്നേഹമാണ്, സ്നേഹം ദൈവമാണ്.',
    'നിങ്ങൾക്ക് പ്രിയമുള്ള ആരോടുകൂടിയിരിക്കുമ്പോൾ, നിങ്ങൾ സ്വർഗത്തിൽ ആകുന്നു.',
    'സമ്പൂർണ്ണ ബ്രഹ്മാണ്ഡം കരുണയാണ്.',
    'ദു:ഖം ദൈവികമായ അനുഗ്രഹമാണ്.',
    'വേദന അനിവാര്യമാണ്, എന്നാൽ ദു:ഖം ആഗ്രഹിക്കുന്നതല്ല.',
    'എല്ലാ മതങ്ങളും ഒന്നാണ്. എല്ലാ മനുഷ്യരും ഒന്നാണ്.',
    'കുടുക്കുന്ന ഹൃദയം, സമാഹരിക്കുന്നു.',
    'സൗമ്യമായിരിക്കുക. പ്രണയം. സേവിക്കുക. ഓർക്കുക.',
    'കഷ്ടപ്പെടേണ്ട. സന്തോഷിക്കൂ. നിന്റെ മികച്ചത് ചെയ്യൂ.',
    'കൃപ സമയം ഇല്ലാതാക്കുന്നു.',
    'ശാന്തി ദൈവത്തിന്റെ ഭാഷയാണ്.',
    'നിന്റെ സ്വഭാവം പ്രേമമാണ്. അതിനെ നിഷേധിക്കരുത്.',
    'ആത്മാവ് ധ്യാനിക്കാൻ ഇഷ്ടപ്പെടുന്നു, കാരണം ആത്മാവിന്റെ ഏറ്റവും വലിയ സന്തോഷം ആത്മാവിന്റെ സമ്പർക്കത്തിലാണു.',
    'എല്ലാം അതിന്റെ സ്വഭാവത്തിൽ തന്നെ സമ്പൂർണ്ണമാണ്.',
    'എല്ലാവരെയും സ്നേഹിക്കുക, എല്ലാവർക്കും സേവനം ചെയ്യുക.',
    'ഇപ്പോൾ സജീവമായിരിക്കുക. ഇവിടെ ഇപ്പോൾ ഉണ്ടാവുക.',
    'മനസ്സിലൂടെ മാത്രമാണ് പുറത്ത് പോകാനുള്ള ഏക മാർഗം.',
    'മനുഷ്യനോടുള്ള സേവനം ദൈവത്തോടുള്ള സേവനമാണ്.',
    'വിടുക, ദൈവത്തെ അനുവദിക്കുക.',
    'വിശ്വാസം ഒരു പക്ഷിയാണ്, അത് പ്രഭാതം ഉയരുന്നുവെന്ന് അനുഭവിക്കുന്നു, എങ്കിലും അന്നും ഇരുണ്ടിരിക്കുമ്പോൾ പാടുന്നു.',
    'മനസ്സ് ആഴം സൃഷ്ടിക്കുന്നു, ഹൃദയം അതിനെ കടക്കുന്നു.',
    'ഹൃദയം നഷ്ടമായതിനെക്കുറിച്ച് കരഞ്ഞാൽ, ആത്മാവ് കണ്ടെത്തിയതിനെക്കുറിച്ച് ചിരിക്കുന്നു.',
    'കരുണ എന്നത് മാനസിക പ്രായപൂർത്തിയുടെയും അതിന്റെ ഏറ്റവും ഉന്നതവും അർത്ഥവത്തായ പ്രതിഫലനമാണ്.',
    'പ്രേമം രണ്ട് ഹൃദയങ്ങൾക്കിടയിലെ പാലമാണ്.',
    'എല്ലാവരെയും സ്നേഹിക്കുക, എല്ലാവരെയും സേവിക്കുക, ദൈവത്തെ ഓർക്കുക. ഇത് നിങ്ങൾക്ക് ആവശ്യമായ എല്ലാ അഭ്യാസവും ആണ്. നിങ്ങൾ ഇത് സത്യസന്ധമായി ചെയ്യാൻ കഴിയുന്നെങ്കിൽ, മറ്റുള്ളവ എല്ലാം സ്വയം വരും.',
    'ഹൃദയം ദൈവം താമസിക്കുന്ന സ്ഥലം ആണ്. നിങ്ങൾ അന്യർക്ക് നിബന്ധനകളില്ലാതെ നിങ്ങളുടെ ഹൃദയം തുറക്കുമ്പോൾ, ദൈവം എപ്പോഴും അവിടെ ഉണ്ടെന്നു നിങ്ങൾ കണ്ടെത്തും.',
    'ലോകം വിട്ടുപോകേണ്ടതാണെന്ന് ചിന്തിക്കേണ്ട. ദൈവം നിന്റെ ജീവിതത്തിന്റെ മദ്ധ്യത്തിൽ, നീ അവനിലേക്കു തിരിയാൻ കാത്തിരിക്കുന്നു.',
    'ദു:ഖം നിങ്ങളെ എവിടെ നിങ്ങൾ ഇപ്പോഴും ബന്ധിപ്പിച്ചിരിക്കുന്നു എന്ന് പഠിപ്പിക്കാൻ വരുന്നു. ബന്ധനം അവസാനിക്കുമ്പോൾ, ദു:ഖത്തിന് നിലനിൽക്കാൻ ഇടം ഇല്ല.',
    'മനസാണ് നിങ്ങളെ ബന്ധിപ്പിക്കുന്നത്, മനസാണ് നിങ്ങളെ മോചിപ്പിക്കുന്നത്. ദൈവത്തെ ഓർമ്മിക്കാൻ അത് പരിശീലിക്കൂ, അതിനാൽ അത് പ്രശ്നങ്ങൾ സൃഷ്ടിക്കുന്നത് നിർത്തും.',
    'നിന്റെ ജോലി ചെയ്യുക, നിന്റെ ഉത്തരവാദിത്വങ്ങൾ കൈകാര്യം ചെയ്യുക, എന്നാൽ നീ ചെയ്യുന്നവനാണെന്ന് ചിന്തിക്കരുത്. എല്ലാം ദൈവം ചെയ്യുന്നു.',
    'നിങ്ങൾ സത്യത്തെ അറിയാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, നിങ്ങളുടെ ആത്മാവിനോട് കള്ളം പറയുന്നത് നിർത്തുക. സാദ്ധ്യമാകുക. സത്യസന്ധമായിരിക്കുക. തിരിച്ചടവ് ചോദിക്കാതെ സ്നേഹിക്കുക.',
    'കോപം, ഇർഷ്യം, ഭയം എന്നിവ നിങ്ങൾ ആരെന്നത് മറന്നുപോയതിന്റെ അടയാളങ്ങളാണ്. ദൈവത്തെ ഓർക്കുക, ഇതൊക്കെയും സ്വാഭാവികമായി അകന്നുപോകും.',
    'നിങ്ങൾ മറ്റുള്ളവരെ നിങ്ങളുടെ സ്വയം മുതൽ വേർപെടുത്തിയതായി കാണുമ്പോൾ, നിങ്ങൾ ദു:ഖിതനാകുന്നു. നിങ്ങൾ എല്ലാവരിലും ദൈവത്തെ കാണുമ്പോൾ, നിങ്ങൾ സ്വതന്ത്രനാകുന്നു.',
    'യാഥാർത്ഥ്യമായ അത്ഭുതം ശരീരം സുഖപ്പെടുത്തുന്നതല്ല. യാഥാർത്ഥ്യമായ അത്ഭുതം അഹംകാരത്തെ നീക്കം ചെയ്യുന്നതാണ്.',
    'നിന്റെ ദു:ഖം നിന്റെ അനുഗ്രഹമാണ്. ഇത് നിന്നെ ഉണർത്താൻ അവിടെ ഉണ്ട്.',
    'നിന്റെ ജീവിതം ഭവനത്തിൽ അല്ലെങ്കിൽ ഭാവിയിൽ ആശങ്കപ്പെടുന്നതിൽ ചെലവഴിക്കരുത്. ദൈവത്തിലും നിന്റെ മുമ്പിൽ ഉള്ളതിലും ശ്രദ്ധ കേന്ദ്രീകരിക്കുക.',
    'നിങ്ങൾ വിശപ്പുള്ളവരെ ഭക്ഷണം നൽകുമ്പോൾ, രോഗികളോട് സേവനം ചെയ്യുമ്പോൾ, ദരിദ്രരെ സഹായിക്കുമ്പോൾ, നിങ്ങൾ നേരിട്ട് ദൈവത്തെ ആരാധിക്കുന്നു.',
    'ശാന്തി ആഗ്രഹിക്കുന്നുവെങ്കിൽ, എല്ലാവരോടും ശാന്തി സ്ഥാപിക്കുക. സ്നേഹം ആഗ്രഹിക്കുന്നുവെങ്കിൽ, സ്നേഹം നിബന്ധനകളില്ലാതെ നൽകുക.',
    'ആത്മാവ് പ്രണയത്തെക്കുറിച്ച് ഭയപ്പെടുന്നു, കാരണം പ്രണയം അതിനെ ലയിപ്പിക്കുന്നു.',
    'എല്ലാം സമ്പൂർണ്ണമാണ്, നിങ്ങൾ അത് കാണാൻ കഴിയുന്നില്ലെങ്കിലും.',
    'നിനക്ക് കൂടുതൽ അറിവിന്റെ ആവശ്യമില്ല. നിനക്ക് കൂടുതൽ സ്നേഹത്തിന്റെ ആവശ്യമുണ്ട്.',
    'നിങ്ങൾ എത്ര ശാന്തനാകുന്നു, അത്രയും നിങ്ങൾ ദൈവത്തെ കേൾക്കാൻ കഴിയും.',
    'മറ്റുള്ളവരെ ന്യായീകരിക്കരുത്. അവർ വഴി ദൈവം എന്ത് പ്രവർത്തനം നടത്തുന്നു എന്ന് നിങ്ങൾക്ക് അറിയില്ല.',
    'വിശ്വാസം നിയന്ത്രണം വിട്ടപ്പോൾ വളരുന്നു.',
    'നിങ്ങൾ ദൈവത്തെ ഓർക്കുമ്പോൾ, ദൈവം നിങ്ങളെ ഓർക്കുന്നു.',
    'നിങ്ങൾ വേർപെടുത്തപ്പെട്ടവനാണെന്ന് ചിന്തിക്കുമ്പോൾ, നിങ്ങൾ ദു:ഖത്തിലേക്ക് വീഴുന്നു.',
    'മറ്റുള്ളവരെ സേവിക്കുക, നിങ്ങൾ ദൈവത്തെ തന്നെ സേവിക്കുന്നതുപോലെ, കാരണം നിങ്ങൾ അതാണ്.',
    'ലോകം ഒരു വിദ്യാലയമാണ്. ഓരോ സാഹചര്യവും നിങ്ങളെ ബന്ധം അല്ലെങ്കിൽ സ്നേഹം സംബന്ധിച്ച എന്തെങ്കിലും പഠിപ്പിക്കുന്നു.',
    'നിന്റെ മുന്നിൽ ഉള്ള വ്യക്തിയെ നീ സ്നേഹിക്കാനാകുന്നില്ലെങ്കിൽ, നീ ദൈവത്തെ സ്നേഹിക്കാനാകില്ല.',
    'നിങ്ങളുടെ കാര്യങ്ങൾ എങ്ങനെ ഉണ്ടായിരിക്കണം എന്നതിനെക്കുറിച്ചുള്ള ആശയങ്ങളെ വിട്ടുവിടുക. എന്താണ് അത് സ്വീകരിക്കുക, നിങ്ങൾ സ്വതന്ത്രനാകും.',
    'സത്യമായ വിട്ടുവീഴ്ച എഗോയെ വിട്ടുവീഴ്ച ചെയ്യുന്നതാണ്, ലോകത്തെ değil.',
    'നിങ്ങൾക്ക് ലോകം മാറ്റേണ്ടതില്ല. നിങ്ങളുടെ ഹൃദയം മാറ്റുക.',
    'ദൈവം എല്ലാം ചെയ്യുന്നു. നിങ്ങൾ വെറും ഉപകരണം മാത്രമാണ്.',
    'ഭയങ്ങൾ അകന്നുപോകുന്നു, നിങ്ങൾ ദൈവത്തിൽ പൂർണ്ണമായും വിശ്വാസം വയ്ക്കുമ്പോൾ.',
    'അവനവിടെ വിനയം ഉണ്ടെങ്കിൽ, ദൈവം വേഗത്തിൽ പ്രവർത്തിക്കുന്നു.',
    'ദൈവത്തെ അത്ഭുതകരമായ അനുഭവങ്ങളിൽ തിരയേണ്ട. പ്രണയത്തിലും സേവനത്തിലും അവനെ അന്വേഷിക്കൂ.',
    'പ്രശ്നം വേദനയല്ല. പ്രശ്നം വേദനയോട് എതിരായിരിക്കുക എന്നതാണ്.',
    'പ്രേമം നിങ്ങളുടെ ഏക പ്രചോദനമാകുമ്പോൾ, ജീവിതം എളുപ്പമാകുന്നു.',
    'നിങ്ങളുടെ അടുക്കൽ വരുന്ന എല്ലാ കാര്യങ്ങളും നിങ്ങളെ ഉണർത്താൻ സഹായിക്കാൻ വരുന്നു.',
    'ദയവാൻ ആയിരിക്കുക. ദയ ഒരു ഉന്നതമായ ജ്ഞാനത്തിന്റെ രൂപമാണ്.',
    'നിങ്ങൾ മോക്ഷം ആഗ്രഹിക്കുന്നുവെങ്കിൽ, മറ്റുള്ളവരെ കുറ്റം പറയുന്നത് നിർത്തുക.',
    'ആത്മാവിന് മെച്ചപ്പെടുത്തലിന്റെ ആവശ്യമില്ല. എങ്കിലും, എഗോയ്ക്ക് അതിന്റെ ആവശ്യമുണ്ട്.',
    'ദൈവം വാക്കുകളിലും ചടങ്ങുകളിലും ആകർഷിതനല്ല. ദൈവം സ്നേഹത്തിന് പ്രതികരിക്കുന്നു.',
    'നിങ്ങൾക്ക് എന്തെങ്കിലും അറിയുന്നുവെന്ന് കരുതുമ്പോൾ, നിങ്ങൾ കൃപയ്ക്ക് അടച്ചുപൂട്ടുന്നു.',
    'സാദ്ധ്യത വ്യക്തതയെ കൊണ്ടുവരുന്നു. വ്യക്തത സമാധാനത്തെ കൊണ്ടുവരുന്നു.',
    'നിന്റെ ആത്മീയ പുരോഗതിയിൽ അഭിമാനിക്കരുത്. അഭിമാനം പുരോഗതിയെ തടയുന്നു.',
    'പ്രേമം നിങ്ങൾ ചെയ്യുന്നതല്ല. ആത്മാവിന്റെ അഹം ഇല്ലായ്മയായപ്പോൾ നിങ്ങൾ ആകുന്ന കാര്യമാണ് പ്രേമം.',
    'ഹൃദയം തുറന്നപ്പോൾ, മനസ്സ് ശാന്തമാകുന്നു.',
    'ദൈവത്തിലേക്ക് എത്താനുള്ള ഏറ്റവും വേഗത്തിലുള്ള വഴി പ്രേമവും സേവനവും ആണ്.',
    'നിങ്ങൾ ഏത് കാര്യത്തോടും ബന്ധപ്പെട്ടു ഇരിക്കുകയാണെങ്കിൽ, അത് നിങ്ങളെ നിയന്ത്രിക്കും.',
    'ദൈവം നിങ്ങളുടെ ജീവിതത്തിന്റെ വേഷത്തിൽ നിങ്ങളെ കാണാൻ വരുന്നു.',
    'സഹനശീലനമായിരിക്കുക. എല്ലാം ശരിയായ സമയത്ത് തന്നെ വെളിപ്പെടുന്നു.',
    'മനസ്സ് അകലം സൃഷ്ടിക്കുന്നു. സ്നേഹം അത് നീക്കുന്നു.',
    'നിന്റെ ആത്മീയ വളർച്ച അളക്കുന്നത് നിർത്തുക. കൂടുതൽ പ്രേമിക്കുക.',
    'നിങ്ങൾ എത്രയും surrendered ചെയ്യുന്നതിന്, ജീവിതം അത്രയും ലഘുവാകുന്നു.',
    'നിങ്ങൾ ആരെങ്കിലും ആണെന്ന് കരുതുകയാണെങ്കിൽ, നിങ്ങൾ ദു:ഖിതനാണ്.',
    'ദൈവത്തെ ആകർഷിക്കാൻ ശ്രമിക്കേണ്ട. സത്യമായിരിക്കുക മാത്രം.',
    'പ്രേമിക്കുന്ന ഹൃദയം ഒരിക്കലും ശൂന്യമാകുന്നില്ല.',
    'അഹംഭാവം ഇല്ലാതെ ചെയ്യുന്ന സേവനം ഉടൻ ശുദ്ധീകരിക്കുന്നു.',
    'ലോകം പ്രശ്നമല്ല. അതിനോടുള്ള നിങ്ങളുടെ ബന്ധമാണ് പ്രശ്നം.',
    'ദൈവം നിങ്ങളുടെ ശ്വാസത്തിൽ ജീവിക്കുന്നു, നിങ്ങളുടെ ചിന്തകളിൽ അല്ല.',
    'നിങ്ങൾ ക്ഷമിക്കാനാകുന്നില്ലെങ്കിൽ, നിങ്ങൾ സ്വതന്ത്രമായിരിക്കാനാവില്ല.',
    'അനുഭവങ്ങളെ പിന്തുടരേണ്ട, സത്യത്തെ പിന്തുടരുക.',
    'നിങ്ങൾ കാണുന്ന ഓരോ വ്യക്തിയും നിങ്ങളുടെ ആത്മീയ അഭ്യാസത്തിന്റെ ഭാഗമാണ്.',
    'നിങ്ങൾ ആവശ്യപ്പെടുന്നത് നിർത്തുമ്പോൾ, ജീവിതം നൽകാൻ തുടങ്ങുന്നു.',
    'കൃപ എപ്പോഴും സാന്നിധ്യത്തിലുണ്ട്. പ്രതിരോധം അതിനെ തടയുന്നു.',
    'നിങ്ങൾ ഇവിടെ എന്തെങ്കിലും നേടാൻ അല്ല, നിങ്ങൾ ഇവിടെ നൽകാൻ ആണ്.',
    'പ്രേമം നിങ്ങളുടെ പ്രവർത്തനങ്ങളെ മാർഗനിർദ്ദേശം ചെയ്യട്ടെ, ഭയം അല്ല.',
    'സന്തോഷം ആഗ്രഹിക്കുന്നുവെങ്കിൽ, ശരിയാവാൻ ശ്രമിക്കുന്നത് നിർത്തുക.',
    'ദൈവം സമ്പൂർണത ആവശ്യപ്പെടുന്നില്ല. ദൈവം സത്യസന്ധത ആവശ്യപ്പെടുന്നു.',
    'ബന്ധം അടിമകളെ ഉണ്ടാക്കുന്നു. പ്രണയം സ്വതന്ത്രരാക്കുന്നു.',
    'സേവനമുണ്ടായിടത്ത്, അവിടെ ദൈവം ഉണ്ട്.',
    'ആത്മാവ് സത്യം ആഗ്രഹിക്കുന്നു. എഗോ അംഗീകാരം ആഗ്രഹിക്കുന്നു.',
    'നിങ്ങൾ ഓടുന്ന എല്ലാം നിങ്ങളെ പിന്തുടരും. നിങ്ങൾ സ്വീകരിക്കുന്ന എല്ലാം നിങ്ങളെ മാറ്റും.',
    'വിശ്വാസം പരീക്ഷിക്കുമ്പോൾ ശക്തമായിരിക്കുന്നു.',
    'ശാന്തത പലപ്പോഴും മികച്ച ഉപദേശമാണ്.',
    'നിന്റെ പാതയെ മറ്റാരുടേയും പാതയുമായി താരതമ്യം ചെയ്യരുത്.',
    'ഹൃദയം മനസ്സ് മനസ്സിലാക്കുന്നതിന് മുമ്പ് അറിയുന്നു.',
    'നിങ്ങൾ നിയന്ത്രിക്കാൻ ശ്രമിക്കുന്നത് നിർത്തുമ്പോൾ, സമാധാനം പ്രത്യക്ഷപ്പെടുന്നു.',
    'പ്രേമം എല്ലാ രോഗങ്ങൾക്കുമുള്ള ഔഷധമാണ്.',
    'ആത്മീയ പാത പ്രത്യേകത നേടുന്നതല്ല. അത് സാധാരണമായതാകുന്നതാണ്.',
    'നിങ്ങൾ നൽകുന്നത്ര, നിങ്ങൾക്ക് ലഭിക്കുന്നതും അത്രയും കൂടുതലാണ്.',
    'ദൈവം നിങ്ങളുടെ സ്വന്തം ചിന്തകളേക്കാൾ അടുത്താണ്.',
    'എല്ലാ ഭയവും നിങ്ങൾ വേറിട്ടവനാണെന്ന് വിശ്വസിക്കുന്നതിൽ നിന്നാണ് വരുന്നത്.',
    'സൗമ്യമായി ജീവിക്കുക. ആഴത്തിൽ സ്നേഹിക്കുക.',
    'നിങ്ങൾ ദൈവത്തിൽ വിശ്വാസം വച്ചാൽ, നിങ്ങൾ പോരാട്ടം നിർത്തും.',
    'കരുണയാണ് ആത്മീയ വളർച്ചയുടെ തെളിവ്.',
    'മനസിന് ഉത്തരം വേണം. ഹൃദയം സമർപ്പണം ആഗ്രഹിക്കുന്നു.',
    'പ്രണയത്തിന്റെ ഓരോ പ്രവൃത്തി നിങ്ങളെ സത്യത്തിലേക്ക് അടുത്തുനയിക്കുന്നു.',
    'നിങ്ങൾ വിധിക്കുന്നത് നിർത്തുക. സ്നേഹിക്കാൻ തുടങ്ങുക.',
    'നിന്റെ ജോലി ഹൃദയം തുറന്ന നിലയിൽ സൂക്ഷിക്കുക എന്നതാണ്.',
    'നിങ്ങൾക്ക് എത്ര കുറവായാലും, നിങ്ങൾ എത്രയും സ്വതന്ത്രനാകും.',
    'ദൈവം എല്ലാം ഉപയോഗിക്കുന്നു — നിങ്ങളുടെ പിഴവുകൾ പോലും.',
    'നിങ്ങളോടും മറ്റുള്ളവരോടും സ്നേഹത്തോടെ പെരുമാറുക.',
    'ആത്മാവിന്റെ അഭിമാനം താരതമ്യത്തിൽ ജീവിക്കുന്നു.',
    'സത്യമായ ശക്തി വിനയത്തിൽ നിന്നാണ് വരുന്നത്.',
    'നിനക്കു യാഥാർത്ഥ്യമുള്ളത് നഷ്ടപ്പെടാൻ കഴിയില്ല.',
    'പ്രേമം മാത്രമാണ് യഥാർത്ഥ പ്രായോഗികത.',
    'നിങ്ങൾ അംഗീകാരം തേടുന്നത് നിർത്തുമ്പോൾ, സമാധാനം എത്തുന്നു.',
    'എല്ലാം ദൈവത്തിനാണ്. ഒന്നും നിന്റെതല്ല.',
    'വിശ്വാസം അർത്ഥമാക്കുന്നത് നിങ്ങൾ മനസ്സിലാക്കാത്തപ്പോൾ പോലും വിശ്വസിക്കുക എന്നതാണ്.',
    'നിന്റെ ജീവിതം നിന്റെ ഉപദേശം ആണ്.',
  ],
  [
    Article(
        heading: 'നിം കരോളി ബാബയുടെ ജീവിതം',
        body: 'നീം കരോലി ബാബ, ബാബ നീബ് കരോറി എന്ന പേരിലും അറിയപ്പെടുന്നു, ഉത്തര ഇന്ത്യയിലെ മലകളിൽ ജീവിച്ചിരുന്ന ഒരു ഹിന്ദു ഗുരുവാണ്. അദ്ദേഹത്തിന്റെ ജന്മ തീയതി വ്യക്തമല്ല, പക്ഷേ 1890-1900 ഇടയിൽ ജനിച്ചിരിക്കുമെന്ന് വിശ്വസിക്കുന്നു. 1973 സെപ്റ്റംബർ 11-ന് അദ്ദേഹം വൃന്ദാവനത്തിലെ ആശുപത്രിയിൽ തന്റെ ശരീരം വിട്ടു.\n\nഅദ്ദേഹത്തിന്റെ അനുകമ്പയുടെയും അത്ഭുതശക്തികളുടെയും പേരിൽ, നീം കരോലി ബാബ എല്ലാ ജീവിതശ്രേണികളിൽ നിന്നുള്ള ഭക്തരെ ആകർഷിച്ചു, 1960-70 കളിൽ നിരവധി പാശ്ചാത്യരെയും ഉൾപ്പെടെ. അദ്ദേഹത്തിന്റെ പാശ്ചാത്യ ഭക്തരിൽ രാം ദാസ് (റിച്ചാർഡ് ആൽപർട്ട്), കൃഷ്ണ ദാസ്, മറ്റ് നിരവധി പേർ ഉൾപ്പെടുന്നു, അവർ അദ്ദേഹത്തിന്റെ ഉപദേശങ്ങൾ പാശ്ചാത്യത്തിലേക്ക് കൊണ്ടുവന്നു.\n\nബാബ തന്റെ ലളിതത്വത്തിനും "എല്ലാവരെയും സ്നേഹിക്കുക, എല്ലാവരെയും സേവിക്കുക, ദൈവത്തെ ഓർക്കുക" എന്ന ഉപദേശത്തിനും അറിയപ്പെടുന്നു. അദ്ദേഹം ഔദ്യോഗികമായ പ്രസംഗങ്ങൾ കുറവായിരുന്നു, തന്റെ സാന്നിധ്യത്തിലൂടെ, പ്രവർത്തനങ്ങളിലൂടെ പഠിപ്പിക്കാൻ ഇഷ്ടപ്പെട്ടു. അവന്റെ ആശ്രമങ്ങൾ എല്ലായ്പ്പോഴും എല്ലാ ആളുകൾക്കും തുറന്നിരുന്നു, ജാതി, മതം, അല്ലെങ്കിൽ ദേശീയതയെ പരിഗണിക്കാതെ.\n\n"നീം കരോലി" എന്ന പേര് അദ്ദേഹം ആദ്യം തന്റെ ഭക്തന്മാർക്ക് പ്രത്യക്ഷപ്പെട്ട ഗ്രാമത്തിൽ നിന്നാണ്, ഒരു നീം മരത്തിന്റെ കീഴിൽ ഇരിക്കുന്നതിലൂടെ. തന്റെ ജീവിതകാലത്ത്, അദ്ദേഹം ഒരേ സമയം പല സ്ഥലങ്ങളിൽ പ്രത്യക്ഷപ്പെടുന്നതിന് അറിയപ്പെടുകയായിരുന്നു, തന്റെ അതീത സ്വഭാവം പ്രകടിപ്പിച്ച്.\n\nഅവന്റെ പാരമ്പര്യം, അദ്ദേഹത്തിന്റെ പേരിൽ നിർമ്മിച്ച അനേകം ആശ്രമങ്ങൾ, ആശുപത്രികൾ, സ്കൂളുകൾ എന്നിവയിലൂടെ, കൂടാതെ അദ്ദേഹത്തിന്റെ അതിരഹിതമായ സ്നേഹവും കരുണയും കൊണ്ട് സ്പർശിച്ച അനേകം ജീവൻമാർ വഴി തുടരുന്നു.'
    ),
    Article(
        heading: 'അനന്തരഹിതമായ പ്രണയത്തിന്റെ അത്ഭുതം',
        body: 'നീം കരോലി ബാബയുടെ ഏറ്റവും ശ്രദ്ധേയമായ വശങ്ങളിൽ ഒന്നാണ് അവന്റെ അനുകൂലമായ സ്നേഹശക്തി. ഏറ്റവും ദരിദ്രനായ begging മുതൽ ഏറ്റവും സമ്പന്നനായ വ്യക്തി വരെ എല്ലാവരോടും അവൻ ഒരേ അതിരില്ലാത്ത സ്നേഹവും ആദരവും കാണിച്ച കഥകൾ നിറഞ്ഞിരിക്കുന്നു.\n\nഅവൻ പലപ്പോഴും പറയാറുണ്ടായിരുന്നു, "സ്നേഹം ഏറ്റവും ശക്തമായ ഔഷധമാണ്," എന്നതിൽ അവൻ പൂര്‍ണമായും ജീവിച്ചു. ഭക്തന്മാർ അവൻ തന്റെ അടുത്തെത്തുന്ന ഏവരെയും ഭക്ഷണം നൽകുന്നതും, ആരും വിശക്കാതെ പോകുന്നില്ലെന്ന് ഉറപ്പാക്കാൻ അത്ഭുതകരമായ രീതിയിൽ ഭക്ഷണം വർദ്ധിപ്പിക്കുന്നതും ഓർമ്മിക്കുന്നു.\n\nഅവന്റെ സ്നേഹം വികാരപരമായ അല്ലെങ്കിൽ സങ്കടപരമായിരുന്നില്ല, മറിച്ച് എല്ലാ ജീവികളിലും ഒരേ ബോധത്തെ കാണുന്ന ശുദ്ധമായ, ദിവ്യമായ സ്നേഹമായിരുന്നു. ഈ സ്നേഹം അവനോടു ബന്ധപ്പെട്ടു വരുന്ന ആയിരക്കണക്കിന് ആളുകളുടെ ജീവിതങ്ങൾ മാറ്റി.\n\nപാശ്ചാത്യ ഭക്തന്മാർ ബാബയുടെ സ്നേഹത്താൽ അവരുടെ മാനസിക പരിക്കുകളും ആത്മീയ തിരച്ചിലുകളും എങ്ങനെ ശാന്തമായുവെന്ന് പലപ്പോഴും പറയുന്നു. രാം ദാസ് പ്രശസ്തമായി പറഞ്ഞത്, നീം കരോലി ബാബയെ കാണുന്നത് തന്റെ ജീവിതം മുഴുവനും മാറ്റിയെന്ന്, അവൻ unconditional പ്രണയം എന്താണെന്ന് കാണിച്ചുവെന്ന്. \n\nബാബ പറഞ്ഞു, ഈ പ്രണയം നേടേണ്ടതല്ല, മറിച്ച് ഓർക്കേണ്ടതാണെന്ന് - ഇത് നമ്മുടെ സത്യ സ്വഭാവമാണ്. മറ്റുള്ളവരെ സേവിച്ച്, നമ്മുടെ ഹൃദയത്തിൽ ദൈവത്തെ സൂക്ഷിക്കുമ്പോൾ, നാം ഇതിനകം ഉള്ള ഈ ദിവ്യ പ്രണയം സ്വാഭാവികമായി പ്രകടിപ്പിക്കുന്നു.'
    ),
    Article(
        heading: 'സേവിക്കുക, സ്നേഹിക്കുക, നൽകുക - ആധാരഭൂതമായ ഉപദേശം',
        body: 'നീം കരോലി ബാബയുടെ പ്രാഥമിക ഉപദേശം മനോഹരമായ സിമ്പിളായിരുന്നു: "സേവിക്കുക, സ്നേഹിക്കുക, നൽകുക, ശുദ്ധീകരിക്കുക, ധ്യാനിക്കുക, സാക്ഷാത്കാരം ചെയ്യുക." ഈ ആറ് വാക്കുകൾ അദ്ദേഹത്തിന്റെ മനസ്സിലനുസരിച്ച് മുഴുവൻ ആത്മീയ പാതയെ ഉൾക്കൊള്ളുന്നു.\n\nസേവനം (Seva) അദ്ദേഹത്തിന്റെ ഉപദേശത്തിന്റെ കേന്ദ്രമായിരുന്നു. അദ്ദേഹം നിരവധി ആശുപത്രികൾ, സ്കൂളുകൾ, ഭക്ഷണ പരിപാടികൾ സ്ഥാപിച്ചു. മറ്റുള്ളവരെ സേവിക്കുന്നത് ഹൃദയം ശുദ്ധീകരിക്കുകയും ദൈവത്തെ സാക്ഷാത്കരിക്കുകയും ചെയ്യാനുള്ള ഏറ്റവും വേഗത്തിലുള്ള മാർഗമാണെന്ന് അദ്ദേഹം പഠിപ്പിച്ചു. "മറ്റുള്ളവരെ സേവിക്കുമ്പോൾ, നിങ്ങൾ ദൈവത്തെ സേവിക്കുന്നു," അദ്ദേഹം പറയ WOULD.\n\nസ്നേഹം ബാബയ്ക്കു ഒരു വികാരമല്ല, എന്നാൽ ആകൃതിയുടെ അടിസ്ഥാനമായിരുന്നു. അദ്ദേഹം തന്റെ ഭക്തികളെ ദിവ്യത്തിന്റെ പ്രതിഫലങ്ങളായ എല്ലാ ജീവികളെയും സ്നേഹിക്കാൻ പ്രേരിപ്പിച്ചു. ഈ സ്നേഹം പ്രായോഗികവും സജീവവുമാകണം, വെറും തത്ത്വചിന്തയല്ല.\n\nനൽകൽ മറ്റൊരു അടിത്തറയായിരുന്നു. ബാബൻ തന്നെ ഒന്നും ഉടമസ്ഥതയിൽ വെച്ചിരുന്നില്ല, എല്ലാം നൽകിക്കഴിഞ്ഞു. അദ്ദേഹം നമ്മൾ നൽകുന്നത് എത്രയും കൂടുതലായാൽ, നമ്മൾ എത്രയും കൂടുതലായാണ് സ്വീകരിക്കുന്നത്, വസ്തുക്കൾ പിടിച്ചിരിക്കുമ്പോൾ ദു:ഖം ഉണ്ടാകുന്നതാണ് എന്ന് പഠിപ്പിച്ചു. \n\nസേവനത്തിലൂടെ, സ്നേഹത്തിലൂടെ, നൽകലിലൂടെ ശുദ്ധീകരണം സ്വാഭാവികമായി സംഭവിക്കുന്നു. ഹൃദയം ശുദ്ധമായപ്പോൾ, ധ്യാനം ആഴത്തിലേക്ക് കടക്കുന്നു, അവബോധം ഉദയിക്കുന്നു. ബാബയ്ക്കു, ഇത് ഒരു രേഖാഖണ്ഡമായ പ്രക്രിയയല്ല, ബഹുവിധ ഘടകങ്ങളുടെ സജീവ പരസ്പര ബന്ധമാണ്.\n\nഅദ്ദേഹത്തിന്റെ സമീപനം പ്രായോഗികവും വീട്ടുകാരനും സന്യാസികൾക്കും ലഭ്യമായതുമായിരുന്നുവെന്ന് തെളിയിക്കുന്നു, സ്നേഹവും സേവനവും നിറഞ്ഞ ഒരു സാധാരണ ജീവിതം നയിക്കുമ്പോൾ പ്രകാശനം സാധ്യമാണ്.'
    ),
    Article(
        heading: 'രാമ്നാമത്തിന്റെ ശക്തി (ദൈവത്തിന്റെ നാമം)',
        body: 'നീം കരോലി ബാബാ ശ്രീ രാമന്റെ മഹാനുഭാവനായ ഭക്തനായിരുന്നു, എന്നും "രാമ, രാമ, രാമ" എന്നത് ജപിച്ചുകൊണ്ടിരുന്നു. ദൈവത്തിന്റെ നാമം (രാമ നാമം) മനുഷ്യരാശിക്ക് ലഭ്യമായ ഏറ്റവും ശക്തമായ ആത്മീയ പ്രാക്ടീസ് ആണെന്ന് അദ്ദേഹം പഠിപ്പിച്ചു.\n\nഈ കാലിയുഗത്തിൽ, ദൈവത്തിന്റെ നാമം ജപിക്കുന്നത് ഏറ്റവും ഫലപ്രദമായ ആത്മീയ പ്രാക്ടീസ് ആണെന്ന് അദ്ദേഹം പലപ്പോഴും പറഞ്ഞിരുന്നു. "രാമ, രാമ, രാമ - ഇത് ഏറ്റവും മഹാനായ മന്ത്രമാണ്," അദ്ദേഹം തന്റെ ഭക്തന്മാർക്ക് പറഞ്ഞു.\n\nബാബാ ദൈവത്തിന്റെ നാമത്തിൽ ദിവ്യത്തിന്റെ മുഴുവൻ ശക്തിയും സാന്നിധ്യവും അടങ്ങിയിരിക്കുന്നുവെന്ന് വിശദീകരിച്ചു. നാം ഭക്തിയോടെ ജപിക്കുമ്പോൾ, ആ ദിവ്യ സാന്നിധ്യം നമ്മുടെ ജീവിതത്തിലേക്ക് ആകർഷിക്കുന്നു. ദൈവത്തിന്റെ നാമത്തിന്റെ ആവർത്തനം മനസും ഹൃദയവും ശുദ്ധീകരിക്കുന്നു, നെഗറ്റിവിറ്റിയെ നീക്കുന്നു, ദിവ്യ ഗുണങ്ങളാൽ നമ്മെ നിറയ്ക്കുന്നു.\n\nരാമ നാമം എപ്പോഴും ജപിക്കാവുന്നതാണ് - ജോലി ചെയ്യുമ്പോഴും, നടക്കുമ്പോഴും, വിശ്രമിക്കുമ്പോഴും. പ്രത്യേകമായ ആകൃതിയോ ചടങ്ങോ ആവശ്യമില്ല. പ്രണയവും ഭക്തിയും കൊണ്ട് സ്ഥിരമായി ഓർക്കൽ ആണ് പ്രധാനമെന്ന്.\n\nബാബയുടെ പഠനപ്രകാരം രാം നാമം ജപിക്കുന്ന ഈ ലളിതമായ പ്രാക്ടീസിലൂടെ നിരവധി ഭക്തന്മാർ ആഴത്തിലുള്ള മാറ്റങ്ങൾ അനുഭവിച്ചു. ഏറ്റവും ആഴത്തിലുള്ള ആത്മീയ പ്രാക്ടീസുകൾ പലപ്പോഴും ഏറ്റവും ലളിതമായവയാണ്, വിദ്യാഭ്യാസം അല്ലെങ്കിൽ സാമൂഹിക സ്ഥാനം എന്നതിനെക്കുറിച്ച് പരിഗണിക്കാതെ എല്ലാവർക്കും ലഭ്യമാണ്.\n\nദിവ്യനാമത്തിന്റെ ശക്തി, ബാബയുടെ അനുസരിച്ച്, ശബ്ദത്തിൽ അല്ല, മറിച്ച് അത് ജപിക്കുമ്പോൾ ഉള്ള പ്രണയവും വിശ്വാസവും ആണ്. "ദൈവം പ്രണയമാണ്, പ്രണയം ദൈവമാണ്," അദ്ദേഹം പറയുന്നതിലൂടെ, ഈ നാമം എല്ലാ പ്രണയത്തിന്റെ ഉറവിടവുമായി നമുക്ക് നേരിട്ട് ബന്ധിപ്പിക്കുന്നു.'
    ),
    Article(
        heading: 'മഹാസമാധി കൂടാതെ അത്ഭുതങ്ങൾക്കും അതിന്റെ അതീത സ്വഭാവത്തിനും ഇടയിൽ ഒരു ബന്ധമുണ്ട്.',
        body: 'നീം കരോലി ബാബയുടെ അത്ഭുതശക്തികളുടെ കഥകൾ അദ്ദേഹത്തിന്റെ ഭക്തന്മാരുടെ ഇടയിൽ പ്രശസ്തമാണ്. അദ്ദേഹം ഒരേ സമയം പല സ്ഥലങ്ങളിൽ പ്രത്യക്ഷപ്പെടാനും, ആളുകൾ സംസാരിക്കാനുള്ള ചിന്തകൾ അറിയാനും, ആവശ്യമായപ്പോൾ ഭക്ഷണവും വസ്തുക്കളും സൃഷ്ടിക്കാനും അറിയപ്പെടുന്നു.\n\nഎന്നാൽ, ബാബൻ ഈ ശക്തികളെ ഒരിക്കലും പ്രധാന്യമാക്കുന്നില്ല. ഭക്തന്മാർ അദ്ദേഹത്തിന്റെ അത്ഭുതങ്ങളിൽ അത്ഭുതപ്പെടുമ്പോൾ, അദ്ദേഹം അവരുടെ ശ്രദ്ധയെ സ്നേഹത്തിലും സേവനത്തിലും തിരിച്ചു കൊണ്ടുപോകും. അത്ഭുതശക്തികളോടുള്ള ആകർഷണം യഥാർത്ഥ ആത്മീയ ലക്ഷ്യത്തിൽ നിന്ന് ശ്രദ്ധ തിരിക്കുന്നതിനുള്ള ഒരു തടസ്സമാകാമെന്ന് അദ്ദേഹം മനസ്സിലാക്കിയിരുന്നു.\n\nഒരു പ്രശസ്തമായ കഥയിൽ, അദ്ദേഹം ഒരു ഭക്തന്റെ ട്രെയിൻ പാതയിൽ പ്രത്യക്ഷപ്പെട്ട് മറിഞ്ഞുപോകുന്നതിൽ നിന്ന് രക്ഷപ്പെടുത്തിയതായി പറയുന്നു. മറ്റൊരു കഥയിൽ, അദ്ദേഹം കുറച്ച് ഭക്ഷണം ആയിരക്കണക്കിന് ആളുകളെ ഭക്ഷിപ്പിക്കാൻ വർദ്ധിപ്പിച്ചതായി recount ചെയ്യുന്നു. പശ്ചിമത്തിലെ ഭക്തന്മാരായ രാം ദാസ് തുടങ്ങിയവർ ബാബയുടെ സർവജ്ഞതയും അത്യാധുനിക കഴിവുകളും സംബന്ധിച്ച അനേകം ഉദാഹരണങ്ങൾ രേഖപ്പെടുത്തി. \n\nഎന്നാൽ ബാബക്കായി, ഈ പ്രത്യക്ഷീകരണങ്ങൾ അദ്ദേഹത്തിന്റെ സ്വാഭാവിക ബോധത്തിന്റെ പ്രകടനങ്ങളായിരുന്നു. എല്ലാ സൃഷ്ടിയും ഒരു ദിവ്യ നാടകമാണെന്ന ബോധത്തിൽ അദ്ദേഹം ജീവിച്ചു, ആ ദർശനത്തിൽ, നാം അത്ഭുതങ്ങൾ എന്ന് വിളിക്കുന്നവ എല്ലാം ഒരേ കോസ്മിക് നൃത്തത്തിലെ വ്യത്യസ്ത ചലനങ്ങളാണ്.\n\nഅദ്ദേഹത്തിന്റെ യഥാർത്ഥ അത്ഭുതം ആളുകളുടെ ഹൃദയങ്ങളിൽ പ്രേമവും ഭക്തിയും ഉണർത്താനുള്ള കഴിവായിരുന്നു. ഭക്തന്മാർ പലപ്പോഴും അദ്ദേഹത്തിന്റെ സാന്നിധ്യത്തിൽ ഇരിക്കുന്നത് തന്നെ ഏറ്റവും വലിയ അത്ഭുതമായിരുന്നു - അവർ എങ്ങനെയായിരുന്നാലും unconditional ആയി പ്രേമിതനും അംഗീകരിതനും ആയ അനുഭവം.\n\nദിവ്യത്തോട് പൂർണ്ണമായും സമർപ്പിക്കുന്ന ആരായിരുന്നാലും ഈ ശക്തികൾ ലഭ്യമാണെന്ന് ബാബ പഠിപ്പിച്ചു. ശക്തികളെ തന്നെ തേടുന്നതല്ല, മറിച്ച് സമ്പൂർണ്ണ ഭക്തിയോടെ ദൈവത്തെ തേടുകയാണ് കീ. തുടർന്ന്, സേവനത്തിനായി ആവശ്യമായ എല്ലാം സ്വാഭാവികമായി പ്രത്യക്ഷപ്പെടും.'
    ),
    Article(
        heading: 'പശ്ചിമ ബന്ധം - രാം ദാസ് എന്നിവരും അതിനപ്പുറം',
        body: '1960-കളുടെ അവസാനം മുതൽ 1970-കളുടെ തുടക്കത്തിൽ, Neem Karoli Baba പാശ്ചാത്യ ലോകത്തേക്ക് Harvard മനശാസ്ത്ര പ്രൊഫസർ Richard Alpert മുഖേന അറിയപ്പെടാൻ തുടങ്ങി, ഇന്ത്യയിൽ ബാബയെ കണ്ട ശേഷം Ram Dass ആയി മാറിയ അദ്ദേഹം.\n\nRam Dass, സൈക്കഡെലിക് വസ്തുക്കളുമായി നടത്തിയ പരീക്ഷണങ്ങൾക്കു ശേഷം ആത്മീയ അനുഭവങ്ങൾ തേടാൻ ഇന്ത്യയിലേക്ക് പോയിരുന്നു. Neem Karoli Babaയെ കണ്ടപ്പോൾ, ഏതെങ്കിലും മയക്കുമരുന്ന് നൽകുന്ന അനുഭവത്തിനേക്കാൾ അകലെയുള്ള ഒരു അനുഭവം കണ്ടെത്തി - ശുദ്ധമായ, അനുകൂലമായ സ്നേഹംയും സ്വീകരണവും.\n\nബാബയുടെ Ram Dass-നോടുള്ള ഇടപെടനം പ്രശസ്തമായിത്തീർന്നു. അവൻ രാം ദാസ് നൽകിയ നിരവധി എൽ.എസ്.ഡി. ടാബുകൾ എടുത്തതായി റിപ്പോർട്ട് ചെയ്യപ്പെടുന്നു, എന്നാൽ അതിന്റെ ഫലങ്ങൾ കാണിച്ചില്ല, "ഇത് ഉപകാരപ്രദമാണ്, എന്നാൽ ഇത് സത്യമായ സമാധി അല്ല" എന്ന് പറഞ്ഞു. ഇത് സാധാരണ ബോധാവസ്ഥകളുടെ മുഴുവൻ അദ്വിതീയതയെ കാണിക്കുന്നു.\n\nരാം ദാസ് എഴുതിയ പുസ്തകങ്ങളിലൂടെ, പ്രത്യേകിച്ച് "ബീ ഹിയർ നൗ" എന്ന പുസ്തകത്തിലൂടെ, ലക്ഷക്കണക്കിന് പാശ്ചാത്യന്മാർ നീം കരോലി ബാബയും അദ്ദേഹത്തിന്റെ ഉപദേശങ്ങളും കുറിച്ച് അറിയുകയും ചെയ്തു. ഇന്ത്യയിലേക്ക് എത്തി അദ്ദേഹത്തെ കാണാൻ പ്രചോദനം ലഭിച്ച നിരവധി ആളുകൾ ഉണ്ടായിരുന്നു, എന്നാൽ 1973-ൽ അദ്ദേഹം തന്റെ ശരീരം വിട്ടുപോകുന്നതിന് മുമ്പ് അദ്ദേഹത്തെ കാണാൻ കഴിയുന്നവരുടെ എണ്ണം കുറവായിരുന്നു.\n\nമ്യൂസിഷ്യൻ കൃഷ്ണ ദാസ് ഉൾപ്പെടെയുള്ള മറ്റ് ശ്രദ്ധേയമായ പാശ്ചാത്യ ഭക്തന്മാർ, പാശ്ചാത്യത്തിലെ മുൻനിര കിർതന കലാകാരന്മാരിൽ ഒരാളായി മാറുകയും, ബാബയുടെ ഉപദേശങ്ങൾ അടിസ്ഥാനമാക്കി ആശ്രമങ്ങൾ, ധ്യാന കേന്ദ്രങ്ങൾ, സേവന സംഘടനകൾ സ്ഥാപിക്കുകയും ചെയ്തു.\n\nബാബയുടെ പാശ്ചാത്യ ആത്മീയതയിൽ ഉള്ള സ്വാധീനം വളരെ വലിയതാണെന്ന് പറയേണ്ടതില്ല. അവൻ സത്യമായ ആത്മീയ സാക്ഷാത്കാരം സാംസ്കാരിക അതിരുകൾ മറികടക്കുന്നതാണ് എന്ന് കാണിച്ചു, സ്നേഹം, സേവനം, ഭക്തി എന്നിവയുടെ സർവ്വജനീന തത്വങ്ങൾ എല്ലായിടത്തും ഹൃദയങ്ങളെ സ്പർശിക്കുന്നു.\n\nഅവന്റെ പാരമ്പര്യം പാശ്ചാത്യത്തിൽ അവന്റെ ഭക്തന്മാർ സ്ഥാപിച്ച നിരവധി അധ്യാപകർ, സംഗീതജ്ഞർ, സേവന സംഘടനകൾ വഴി തുടരുന്നു, എല്ലാം സ്നേഹവും സേവനവും എന്ന അവന്റെ അടിസ്ഥാന സന്ദേശം മുന്നോട്ട് കൊണ്ടുപോകുന്നു.'
    ),
    Article(
        heading: 'ആശ്രങ്ങൾക്കും സേവന പദ്ധതികൾക്കും',
        body: 'ജീവിതകാലം മുഴുവൻ, നീം കരോലി ബാബാ നിരവധി ആശ്രമങ്ങൾ, ക്ഷേത്രങ്ങൾ, ആശുപത്രികൾ, സ്കൂളുകൾ സ്ഥാപിച്ചു. സേവനത്തിലേക്ക് അദ്ദേഹത്തിന്റെ സമീപനം സമഗ്രമായിരുന്നു, ആളുകളുടെ ആത്മീയവും ഭൗതികവുമായ ആവശ്യങ്ങൾക്കു നേരിട്ടുള്ള പരിഹാരങ്ങൾ നൽകുകയായിരുന്നു.\n\nബാബയുമായുള്ള പ്രധാന ആശ്രമങ്ങൾ നൈനിതാലിന് സമീപമുള്ള കൈന്ചി ധാം, വൃന്ദാവനം, കൂടാതെ ഹിമാലയൻ കുന്നുകളിൽ മറ്റ് നിരവധി സ്ഥലങ്ങളാണ്. 1964-ൽ സ്ഥാപിതമായ കൈന്ചി ധാം, ഏറ്റവും പ്രശസ്തമായതും, ഓരോ വർഷവും ആയിരക്കണക്കിന് ഭക്തരെ ആകർഷിക്കുന്നതും ആയി മാറി.\n\nബാബയുടെ സേവന പദ്ധതികൾ വ്യാപകമായിരുന്നു. ദരിദ്രരെ സേവിക്കാൻ ആശുപത്രികൾ നിർമ്മിച്ചു, കുട്ടികളെ അവരുടെ സാമ്പത്തിക ശേഷിയേക്കാൾ സ്വതന്ത്രമായി വിദ്യാഭ്യാസം നൽകുന്ന സ്കൂളുകൾ സ്ഥാപിച്ചു, ഇന്നും തുടരുന്ന ഭക്ഷണ പരിപാടികൾ നടപ്പിലാക്കി. മനുഷ്യത്വത്തെ സേവിക്കുന്നത് ആരാധനയുടെ ഉയർന്ന രൂപമാണെന്ന് അദ്ദേഹം വിശ്വസിച്ചിരുന്നു.\n\nഅദ്ദേഹത്തിന്റെ മാർഗ്ഗനിർദ്ദേശത്തിൽ നിർമ്മിച്ച ആശുപത്രികൾ, ആവശ്യമായ എല്ലാവർക്കും സൗജന്യമായ വൈദ്യസഹായം നൽകുകയായിരുന്നു. അവൻ സ്ഥാപിച്ച സ്കൂളുകൾ ജാതി, മതം, അല്ലെങ്കിൽ സാമ്പത്തിക നിലയുടെ അടിസ്ഥാനത്തിൽ വിവേചനം ഇല്ലാതെ വിദ്യാഭ്യാസം നൽകുകയായിരുന്നു. തന്റെ കാലഘട്ടത്തിലെ സാമൂഹിക സാഹചര്യത്തിൽ ഇത് വിപ്ലവാത്മകമായിരുന്നു.\n\nഅവന്റെ ഭക്തർ ഇന്നും ഈ സേവന പരമ്പരകൾ തുടരുന്നു. നീം കരോലി ബാബാ ആശ്രമ സംഘടനകൾ ലോകമെമ്പാടും നിരവധി ദാന പദ്ധതികൾ നടത്തുന്നു, ഇതിൽ മെഡിക്കൽ ക്ലിനിക്കുകൾ, സ്കൂളുകൾ, ഭക്ഷണ പരിപാടികൾ, ദുരിതാശ്വാസ ശ്രമങ്ങൾ എന്നിവ ഉൾപ്പെടുന്നു.\n\nബാബാ ഈ സേവന പദ്ധതികൾ ആത്മീയ അഭ്യാസത്തിൽ നിന്ന് വേർപെടുത്തിയതല്ല, മറിച്ച് അത് തന്നെ ആത്മീയ അഭ്യാസമാണെന്ന് പഠിപ്പിച്ചു. മറ്റുള്ളവരെ, പ്രത്യേകിച്ച് ദരിദ്രരെയും ദു:ഖിതരെയും സേവിക്കുന്നതിലൂടെ, ഭക്തന്മാർ അവരുടെ ഹൃദയങ്ങളെ ശുദ്ധീകരിക്കുകയും ദൈവത്തോടു അടുത്തുവരുകയും ചെയ്യുന്നു. \n\nആശ്രമങ്ങൾ ആരാധനയുടെ സ്ഥലങ്ങളായിരിക്കാതെ സേവനത്തിന്റെ കേന്ദ്രങ്ങളായും പ്രവർത്തിക്കുന്നു, ആത്മീയതയും സേവനവും ദൈവീയ പ്രണയത്തിന്റെ ഒരേ പ്രവർത്തനത്തിലെ അപ്രവർത്തനീയമായ അംശങ്ങളാണെന്ന് ബാബയുടെ ദർശനത്തെ തുടർന്നാണ്.'
    ),
    Article(
        heading: 'അർപ്പണം ಮತ್ತು വിശ്വാസത്തിന്റെ ഉപദേശം',
        body: 'നീം കരോലി ബാബയുടെ കേന്ദ്ര ഉപദേശങ്ങളിൽ ഒന്നാണ് ദിവ്യത്തോടുള്ള സമ്പൂർണ്ണ സമർപ്പണത്തിന്റെ പ്രാധാന്യം. അദ്ദേഹം പലപ്പോഴും പറഞ്ഞത്, "വിടുവാൻ വിടുക, ദൈവത്തോട് വിടുക," എന്നതാണ്, നമ്മുടെ ജീവിതത്തെ നിയന്ത്രിക്കാൻ ഉള്ള ശ്രമങ്ങൾ ദു:ഖം സൃഷ്ടിക്കുന്നു എന്ന് പഠിപ്പിക്കുന്നത്.\n\nബാബ തന്റെ ജീവിതത്തിൽ സമ്പൂർണ്ണ സമർപ്പണം പ്രദർശിപ്പിച്ചു. അദ്ദേഹത്തിന് ഒന്നും ഉണ്ടായിരുന്നില്ല, ഒന്നും പദ്ധതിയിടുന്നില്ല, എന്നാൽ തന്റെ സേവനത്തിനായി ആവശ്യമായ എല്ലാം എപ്പോഴും പ്രത്യക്ഷമായിരുന്നു. അദ്ദേഹം ദിവ്യ പ്രദാനം എന്നതിൽ സമ്പൂർണ്ണമായ വിശ്വാസം പുലർത്തി, തന്റെ ഭക്തരെ അതുപോലെ ചെയ്യാൻ പഠിപ്പിച്ചു.\n\nസമർപ്പണം പാസ്സിവിറ്റിയല്ല, മറിച്ച് ദിവ്യ ഇച്ഛയോടൊപ്പം നമ്മുടെ ഇച്ഛയെ സംയോജിപ്പിക്കുകയാണ് എന്ന് അദ്ദേഹം വിശദീകരിച്ചു. നമ്മുടെ ആത്മാവിന്റെ ആഗ്രഹങ്ങളും ഭയങ്ങളും സമർപ്പിക്കുമ്പോൾ, ദൈവം ലോകത്തിൽ പ്രവർത്തിക്കാൻ കഴിവുള്ള ഉപകരണങ്ങളാകുന്നു.\n\nവിശ്വാസം അദ്ദേഹത്തിന്റെ ഉപദേശത്തിന്റെ മറ്റൊരു അടിത്തറയായിരുന്നു. അവൻ പറഞ്ഞു, "വിശ്വാസം ഒരു പക്ഷിയാണ്, അത് പ്രഭാതം വരുന്നത് അനുഭവിച്ച്, ഇനിയും ഇരുട്ടിലാണ് പാടുന്നത്." ഈ വിശ്വാസം അന്ധവിശ്വാസമല്ല, മറിച്ച് സൃഷ്ടിയുടെ അടിസ്ഥാന നല്ലതിലും ബുദ്ധിയിലും ആഴത്തിലുള്ള വിശ്വാസമാണ്.\n\nബാബ പറഞ്ഞു, സംശയവും ആശങ്കയും സ്വയം ദുർവ്യവഹാരത്തിന്റെ രൂപങ്ങളാണ്, അവയ്ക്ക് യാതൊരു ഉപകാരവുമില്ല. ഭാവിയെക്കുറിച്ച് ആശങ്കപ്പെടുന്നതിന് പകരം, ഭക്തരെ ഇപ്പോഴത്തെ നിമിഷത്തിൽ സേവനവും സ്നേഹവും ചെയ്യാൻ പ്രോത്സാഹിപ്പിച്ചു, ഭാവി സ്വയം പരിചാലിക്കുമെന്ന് വിശ്വസിച്ച്.\n\nഅവന്റെ സ്വന്തം ജീവിതം ഈ ഉപദേശത്തിന്റെ ഒരു സമ്പൂർണ്ണ ഉദാഹരണമാണ്. ഭൗതിക സുരക്ഷ ഇല്ലാത്തതിനാൽ പോലും, അദ്ദേഹം സമ്പൂർണ്ണ സന്തോഷത്തിലും സമാധാനത്തിലും ജീവിച്ചു, ആയിരക്കണക്കിന് ഭക്തന്മാരുടെ പരിചരണവും അനേകം സേവന പദ്ധതികളുടെ പരിപാലനവും ദിവ്യ കൃപയിലൂടെ മാത്രം നടത്തി.\n\nബാബയ്ക്കു, സമർപ്പണംയും വിശ്വാസവും ആത്മീയ ആശയങ്ങൾ മാത്രമല്ല, ലോകത്ത് കൂടുതൽ ഫലപ്രദത, സന്തോഷം, സേവനം എന്നിവയിലേക്ക് എത്തിക്കുന്ന പ്രായോഗിക സമീപനങ്ങളാണ്.'
    ),
    Article(
        heading: 'ആഗോള സന്ദേശം - എല്ലാ മതങ്ങളും ഒരൊറ്റവണ്ണമാണ്',
        body: 'നിം കരോളി ബാബാ എല്ലാ മതങ്ങളും സത്യത്തിലേക്ക് എത്തിക്കുന്നുവെന്ന്, സത്യസന്ധതയും ഭക്തിയും കൊണ്ട് പ്രയോഗിച്ചാൽ, പഠിപ്പിച്ചു. അദ്ദേഹം പറയാറുണ്ടായിരുന്നു, "എല്ലാ മതങ്ങളും ഒന്നാണ്. എല്ലാ മനുഷ്യരും ഒന്നാണ്," എന്ന വിശ്വാസം അദ്ദേഹം എല്ലാ മതക്കാരുമായുള്ള ഇടപെടലുകൾ വഴി പ്രകടിപ്പിച്ചു.\n\nഅദ്ദേഹത്തിന്റെ ആശ്രമങ്ങൾ മത പശ്ചാത്തലമില്ലാതെ ആളുകളെ സ്വീകരിച്ചു. ക്രിസ്ത്യന്മാർ, മുസ്ലിംകൾ, ബുദ്ധമതക്കാരൻ, യഹൂദന്മാർ, ഹിന്ദുക്കൾ, ഔദ്യോഗിക മതമില്ലാത്ത ആളുകൾ, എല്ലാം അദ്ദേഹത്തിന്റെ സാന്നിധ്യത്തിൽ സ്വീകരണംയും സ്നേഹവും കണ്ടെത്തി. അദ്ദേഹം പുറം മത രൂപങ്ങളെക്കാൾ കടന്നുപോയി, എല്ലാ പരമ്പരകളിലെയും ആഗോള ആത്മീയ സാരത്തെ കണ്ടു.\n\nബാബാ ക്രിസ്തുവിനെ വലിയ ആദരത്തോടെ സംസാരിക്കാറുണ്ടായിരുന്നു, ക്രിസ്തും രാമും വ്യത്യസ്ത രൂപങ്ങളിൽ പ്രത്യക്ഷപ്പെടുന്ന ഒരേ ദിവ്യ ബോധമാണെന്ന് പറഞ്ഞു. അവൻ ഈ അടിസ്ഥാന ഐക്യത്തിന്റെ അജ്ഞാനത്തിൽ നിന്നാണ് മത സംഘർഷങ്ങൾ ഉയരുന്നത് എന്ന് പഠിപ്പിച്ചു. \n\nഅവൻ തന്റെ ഭക്തരെ മറ്റൊരു മതത്തിലേക്ക് മാറുന്നതിന് പകരം, അവരുടെ സ്വന്തം മതപരമ്പരകളെ കൂടുതൽ ആഴത്തിൽ പ്രയോഗിക്കാൻ പ്രചോദിപ്പിച്ചു. ഒരു ക്രിസ്ത്യൻ ഭക്തനെ കൂടുതൽ നല്ല ക്രിസ്ത്യൻ ആകാൻ പ്രചോദിപ്പിക്കപ്പെടും, ഒരു മുസ്ലിം ഭക്തനെ കൂടുതൽ നല്ല മുസ്ലിം ആകാൻ, ഇങ്ങനെ തന്നെ.\n\nഈ ഉൾക്കൊള്ളുന്ന സമീപനം ക്രമീകരിച്ച മതത്തിൽ നിരാശയിലായ നിരവധി പാശ്ചാത്യ ഭക്തന്മാർക്കായി വിപ്ലവാത്മകവും ചികിത്സാത്മകവുമായിരുന്നു. ബാബാ അവരെ മതപരമായ അതിരുകൾ മറികടക്കുന്നതും എല്ലാ സത്യമായ ആത്മീയ പാതകളെ ആദരിക്കുന്നതും എങ്ങനെ ആത്മീയത ഉയർത്തുന്നു എന്ന് കാണിച്ചു.\n\n"ദൈവം സ്നേഹമാണ്, സ്നേഹം ദൈവമാണ്" എന്ന അദ്ദേഹത്തിന്റെ പഠനം എല്ലാ പശ്ചാത്തലങ്ങളിലുള്ള ആളുകൾക്കായി ഒരു പൊതുവായ നിലയുണ്ടാക്കി. ദൈവത്തെ അവർ എങ്ങനെ ധാരണ ചെയ്താലും, എല്ലാവരും പ്രണയം മനസ്സിലാക്കുകയും അഭ്യസിക്കയും ചെയ്യാം. \n\nഈ സർവജനീന സന്ദേശം, നമ്മുടെ കൂടുതൽ ബന്ധിതമായെങ്കിലും പലപ്പോഴും വിഭജിതമായ ലോകത്ത്, വൈവിധ്യത്തെ മാനിക്കുന്ന ഒരു ഐക്യത്തിന്റെ ദർശനം നൽകുന്നു, അതേ സമയം എല്ലാ യഥാർത്ഥ മതപരമായ അന്വേഷണങ്ങളുടെ സാധാരണ ആത്മീയ ഹൃദയത്തെ അംഗീകരിക്കുന്നു.'
    ),
    Article(
        heading: 'ഇന്നത്തെ ദിനത്തിൽ ഉപദേശങ്ങൾ ജീവിക്കുക',
        body: 'നീം കരോലി ബാബയുടെ ഉപദേശങ്ങൾ അദ്ദേഹത്തിന്റെ ജീവിതകാലത്ത് പോലെ ഇന്നും അത്ര തന്നെ പ്രസക്തമാണ്. സമ്മർദം, സംഘർഷം, അനിശ്ചിതത്വം നിറഞ്ഞ ആധുനിക ലോകത്തിൽ, സ്നേഹവും സേവനവും എന്ന അദ്ദേഹത്തിന്റെ ലളിതമായ സന്ദേശം സമാധാനവും സംതൃപ്തിയും നേടാനുള്ള ഒരു പ്രായോഗിക പാത നൽകുന്നു.\n\nഅദ്ദേഹത്തിന്റെ പ്രധാന ഉപദേശം - "എല്ലാവരെയും സ്നേഹിക്കുക, എല്ലാവരെയും സേവിക്കുക, ദൈവത്തെ ഓർക്കുക" - ഏത് ജീവിത സാഹചര്യത്തിലും പ്രയോഗിക്കാവുന്നതാണ്. നാം മാതാപിതാക്കൾ, പ്രൊഫഷണലുകൾ, വിദ്യാർത്ഥികൾ അല്ലെങ്കിൽ വിരമിച്ചവരായിട്ടുണ്ടെങ്കിലും, നാം ഈ തത്വങ്ങളെ നമ്മുടെ ദൈനംദിന പ്രവർത്തനങ്ങളിൽ പ്രയോഗിക്കാം.\n\nമറ്റുള്ളവരെ സേവിക്കുന്നത് ഒരു സംഘടനയിലേക്ക് ചേരുകയോ ദൂരസ്ഥ സ്ഥലങ്ങളിലേക്ക് യാത്ര ചെയ്യുകയോ ചെയ്യേണ്ടതില്ല. ഇത് ഒരു സഹായത്തിനായി ആവശ്യമുള്ള സുഹൃത്തിനോട് കേൾക്കുന്നതാണ്, ഒരു പ്രായമായ അയൽക്കാരനെ സഹായിക്കുന്നതാണ്, അല്ലെങ്കിൽ സഹപ്രവർത്തകരോട് ദയയും ആദരവും കാണിക്കുന്നതാണ്. ബാബ പറഞ്ഞു, സ്നേഹവും സ്വയംക്ഷമതയും കൊണ്ട് ചെയ്ത ഏത് പ്രവൃത്തി ദൈവത്തോടുള്ള സേവനമാണ്.\n\nദൈവത്തെ ഓർക്കുന്നത് പ്രാർത്ഥന, ജപനം, ധ്യാനം, അല്ലെങ്കിൽ നന്ദിയും ബോധവും നിലനിർത്തുന്നതിലൂടെ ദിനംപ്രതി സംഭവിക്കാം. ദിവ്യത്തെ സ്ഥിരമായി ഓർക്കുന്നത് സാധാരണ പ്രവർത്തനങ്ങളെ ആത്മീയ പ്രാക്ടീസിലേക്ക് മാറ്റുന്നതിൽ ബാബ വലിയ പ്രാധാന്യം നൽകി.\n\nബാബയ്ക്ക് വളരെ പ്രധാനപ്പെട്ട "ജനങ്ങളെ ഭക്ഷണം നൽകുക" എന്ന പ്രാക്ടീസ് ശാരീരികമായോ, മാനസികമായോ, അല്ലെങ്കിൽ ആത്മീയമായോ ആകാം. ഭക്ഷണം, സ്നേഹം, പ്രോത്സാഹനം, അല്ലെങ്കിൽ ജ്ഞാനം പങ്കുവെച്ച്, നമ്മുടെ കഴിവുകൾക്കും സാഹചര്യങ്ങൾക്കും അനുസൃതമായി, മറ്റുള്ളവരെ നാം ഭക്ഷണം നൽകാം.\n\n"സത്യം പറയുക" എന്ന അദ്ദേഹത്തിന്റെ ഉപദേശം, സത്യസന്ധത പലപ്പോഴും കുഴപ്പത്തിലാകുന്ന ഒരു ലോകത്തിൽ കൂടുതൽ പ്രാധാന്യമർഹിക്കുന്നു. സത്യമായി ജീവിക്കുന്നത് നമ്മുടെ ബന്ധങ്ങളിൽ സത്യസന്ധമായിരിക്കാനും മറ്റുള്ളവരോടുള്ള ഇടപെടലുകളിൽ സത്യസന്ധത പുലർത്താനും അർത്ഥമാക്കുന്നു. \n\nആധുനിക ഭക്തന്മാർ ബാബയുടെ ഉപദേശങ്ങൾ പ്രവർത്തിക്കുന്നു എന്ന് കണ്ടെത്തുന്നു. സ്നേഹം, സേവനം, ഓർമ്മ എന്നിവ പ്രാക്ടീസ് ചെയ്യുന്നതിലൂടെ, ആളുകൾ കൂടുതൽ സന്തോഷം, മികച്ച ബന്ധങ്ങൾ, ജീവിതത്തിൽ ആഴത്തിലുള്ള അർത്ഥവും ലക്ഷ്യവും അനുഭവിക്കുന്നു.'
    ),
  ],
);
